using System;
using System.Collections;
using UnityEngine;

/// <summary>
/// A player's token: a top-down illustrated subway car (with a soft shadow) that drives
/// along the board, turning to face the direction of travel.
///
/// Artwork: Resources/Tokens/car_{slot}.png (one per player colour) and car_shadow.png,
/// generated by tools/make_tokens.py. Each player drives in their own lane across the
/// squares, so several cars on one square sit side by side instead of piling up.
///
/// Usage:
///   var token = PlayerToken.Create(slotIndex, boardIndex);
///   token.SnapTo(boardIndex);
///   token.MoveTo(targetIndex, () => Debug.Log("arrived"));
/// </summary>
public class PlayerToken : MonoBehaviour
{
    // -- Look ----------------------------------------------------------------
    private const int   SlotCount   = 4;           // car_0 .. car_3
    private const float CarLength   = 0.85f;       // world units, nose to tail (a square is ~1.43)
    private const float CarPixels   = 480f;        // car length within the 512 px texture (make_tokens.py)
    private const int   ShadowOrder = 6;           // above the card pile (5)
    private const int   CarOrder    = 7;           // below a card flying to a token (8) and the spinner (10)
    private static readonly Vector3 ShadowOffset = new Vector3(0.035f, -0.05f, 0f);   // light from top-left

    // Lane offsets across the track (world units), so cars sharing a square sit side by side.
    private static readonly float[] Lanes = { 0.17f, -0.17f, 0.48f, -0.48f };

    // -- Motion --------------------------------------------------------------
    private const float TokenZ    = -0.5f;         // in front of the board
    private const float MoveSpeed = 0.18f;         // seconds per square
    private const float HopScale  = 0.08f;         // slight "bounce" while hopping between squares

    // The board is 22 squares: 0-5 top (→), 6-10 right (↓), 11-16 bottom (←), 17-21 left (↑)
    private static float DirectionZ(int boardIndex)
    {
        if (boardIndex <= 5)  return   0f;   // top row:    facing right
        if (boardIndex <= 10) return -90f;   // right col:  facing down
        if (boardIndex <= 16) return 180f;   // bottom row: facing left
        return                          90f; // left col:   facing up
    }

    // -- State ---------------------------------------------------------------
    private int       _slot;
    private int       _boardIndex;   // square the token is on (or heading to while moving)
    private bool      _moving;
    private Transform _car;
    private Transform _shadow;

    // Tap-zone transforms, looked up once (zones live for the whole session).
    private static readonly Transform[] ZoneCache = new Transform[BoardManager.BoardSize];

    // -- Lifecycle -----------------------------------------------------------

    void OnEnable()  => BoardDisplay.OnBoardFitted += HandleBoardFitted;
    void OnDisable() => BoardDisplay.OnBoardFitted -= HandleBoardFitted;

    /// <summary>Screen rotated or resized: the board moved, so follow it.</summary>
    private void HandleBoardFitted()
    {
        if (!_moving) SnapTo(_boardIndex);   // a move in progress re-targets every frame
    }

    // -- Factory -------------------------------------------------------------

    /// <summary>Creates and returns a token for the given player slot at boardIndex.</summary>
    public static PlayerToken Create(int slot, int boardIndex)
    {
        int safeSlot = Mathf.Clamp(slot, 0, SlotCount - 1);

        var root = new GameObject($"PlayerToken_Slot{safeSlot}");
        DontDestroyOnLoad(root);

        var token = root.AddComponent<PlayerToken>();
        token._slot = safeSlot;
        token.BuildSprites();
        token.SnapTo(boardIndex);
        return token;
    }

    // -- Public API ----------------------------------------------------------

    /// <summary>Instantly moves the token to boardIndex.</summary>
    public void SnapTo(int boardIndex)
    {
        _boardIndex = boardIndex;
        transform.position   = SquareWorldPos(boardIndex);
        transform.localScale = Vector3.one;
        SetHeading(DirectionZ(boardIndex));
    }

    /// <summary>
    /// Animates the token to targetIndex (callers move one square at a time).
    /// Calls onComplete when done.
    /// </summary>
    public void MoveTo(int targetIndex, Action onComplete)
    {
        StartCoroutine(MoveCoroutine(targetIndex, onComplete));
    }

    // -- Coroutine -----------------------------------------------------------

    private IEnumerator MoveCoroutine(int target, Action onComplete)
    {
        // Endpoints are recomputed each frame from the squares, so a screen
        // rotation or resize mid-move still lands on the right square.
        int   from      = _boardIndex;
        float startRot  = _car != null ? _car.localEulerAngles.z : 0f;
        float targetRot = DirectionZ(target);
        float elapsed   = 0f;

        _moving     = true;
        _boardIndex = target;

        while (elapsed < MoveSpeed)
        {
            elapsed += Time.deltaTime;
            float t = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(elapsed / MoveSpeed));
            transform.position   = Vector3.Lerp(SquareWorldPos(from), SquareWorldPos(target), t);
            transform.localScale = Vector3.one * (1f + HopScale * Mathf.Sin(t * Mathf.PI));
            SetHeading(startRot + Mathf.DeltaAngle(startRot, targetRot) * t);
            yield return null;
        }

        transform.position   = SquareWorldPos(target);
        transform.localScale = Vector3.one;
        SetHeading(targetRot);
        _moving = false;
        onComplete?.Invoke();
    }

    // -- Geometry helpers ----------------------------------------------------

    private void SetHeading(float zDegrees)
    {
        // Only the car and its shadow rotate; the shadow's offset stays fixed (light from top-left).
        var rot = Quaternion.Euler(0f, 0f, zDegrees);
        if (_car    != null) _car.localRotation    = rot;
        if (_shadow != null) _shadow.localRotation = rot;
    }

    private Vector3 SquareWorldPos(int boardIndex)
    {
        int i = ((boardIndex % BoardManager.BoardSize) + BoardManager.BoardSize) % BoardManager.BoardSize;
        if (ZoneCache[i] == null)
        {
            var found = GameObject.Find($"TapZone_{i:D2}");
            if (found == null) return Vector3.zero;
            ZoneCache[i] = found.transform;
        }

        // Offset sideways from the direction of travel into this player's lane.
        float a = DirectionZ(i) * Mathf.Deg2Rad;
        var across = new Vector3(-Mathf.Sin(a), Mathf.Cos(a), 0f);
        float lane = Lanes[Mathf.Clamp(_slot, 0, Lanes.Length - 1)];

        return ZoneCache[i].position + across * lane + new Vector3(0f, 0f, TokenZ);
    }

    // -- Sprites -------------------------------------------------------------

    private void BuildSprites()
    {
        _shadow = MakeChild("Shadow", LoadSprite("Tokens/car_shadow"), ShadowOrder);
        _shadow.localPosition = ShadowOffset;
        _car = MakeChild("Car", LoadSprite($"Tokens/car_{_slot}"), CarOrder);
    }

    private Transform MakeChild(string name, Sprite sprite, int order)
    {
        var go = new GameObject(name);
        go.transform.SetParent(transform, false);
        var sr = go.AddComponent<SpriteRenderer>();
        sr.sprite = sprite;
        sr.sortingOrder = order;
        return go.transform;
    }

    private static Sprite LoadSprite(string path)
    {
        var tex = Resources.Load<Texture2D>(path);
        if (tex == null)
        {
            Debug.LogError($"[PlayerToken] Missing Resources/{path}.png (run tools/make_tokens.py; is Git LFS installed?).");
            tex = Texture2D.whiteTexture;
            return Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 0.5f),
                                 tex.width / CarLength);
        }

        // The car spans CarPixels of a 512 px-wide texture; scale so it is CarLength world units long.
        float carPx = CarPixels * tex.width / 512f;
        return Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 0.5f),
                             carPx / CarLength);
    }
}
